34	  void custom_thread()
35	  {
36	    auto ext = new axi::axi4_extension;
37	    tlm::tlm_command cmd =
38	      static_cast<tlm::tlm_command>(tlm::TLM_WRITE_COMMAND);
39	
40	    // prepare a reused payload
41	    tlm::tlm_generic_payload* trans = new tlm::tlm_generic_payload;
42	    trans->set_command(cmd);
43	    trans->set_data_length(1);
44	    trans->set_streaming_width(1); // = data_length to indicate no streaming
45	    trans->set_byte_enable_ptr(0); // 0 indicates unused
46	    trans->set_dmi_allowed(false); // Mandatory initial value
47	    trans->set_extension(ext);
48	    // Mandatory initial value
49	    trans->set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
50	
51	    for (int i = 0; i < 100; i++) {
52	      wait(this->clk.posedge_event());
53	    }
54	
55	    while (1) {
56	      custom_master_sem.wait();
57	
58	      unsigned long long base;
59	
60	      switch (subport_test) {
61	      case SubPortTest::TEST_ILM:
62	        base = ilm_base;
63	        break;
64	      case SubPortTest::TEST_DLM:
65	        base = dlm_base;
66	        break;
67	      case SubPortTest::TEST_HVM:
68	        base = hvm_base;
69	        break;
70	      default:
71	        continue;
72	        break;
73	      }
74	
75	      unsigned long long end = base + sizeof(test_data);
76	
77	      for (unsigned long long addr = base, i = 0; addr < end; addr += 1, i++) {
78	
79	        trans->set_address(addr);
80	        trans->set_data_ptr(test_data + i);
81	
82	        sc_core::sc_time delay = sc_core::SC_ZERO_TIME;
83	        this->socket->b_transport(*trans, delay);
84	
85	        // Initiator obliged to check response status
86	        if (trans->is_response_error())
87	          SC_REPORT_ERROR("TLM-2", "Response error from b_transport");
88	
89	        auto ts = sc_core::sc_time_stamp().to_double();
90	        spdlog::debug("trans = {}, {:#x} , data = {:#x} at time {}",
91	                      (cmd ? 'W' : 'R'), addr, test_data[i], ts);
92	
93	        wait(this->clk.posedge_event());
94	      }
95	    }
96	  }
97	};
