46	template<std::size_t BusWidth = 32>
47	class SimControl : public sc_core::sc_module
48	{
49	public:
50	  using sys_func_ptr = uint64_t (SimControl::*)(
51	    uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, uint64_t);
52	
