57	  SimControl(const sc_core::sc_module_name& name,
58	             const MemoryRegion& region,
59	             SimpleMemory<BusWidth>& main_memory,
60	             sc_core::sc_signal<sc_dt::sc_uint<31>>& int_trigger,
61	             const sc_core::sc_clock& clk)
62	      : sc_core::sc_module{name},
63	        exits(-1),
64	        region(region),
65	        data_region(main_memory),
66	        int_trigger(int_trigger),
67	        clk(clk),
68	        riscv_xlen(0),
69	        partial_htif_command(0),
70	        htif_parts_received(0)
71	  {
72	    sim_syscall_table[5] = &SimControl::handle_gettimeofday;
73	    sim_syscall_table[6] = &SimControl::handle_open;
74	    sim_syscall_table[7] = &SimControl::handle_write;
75	    sim_syscall_table[8] = &SimControl::handle_getcwd;
76	    sim_syscall_table[9] = &SimControl::handle_lseek;
77	    sim_syscall_table[10] = &SimControl::handle_read;
78	    sim_syscall_table[11] = &SimControl::handle_flen;
79	    sim_syscall_table[12] = &SimControl::handle_close;
