82	    sim_syscall_table[15] = &SimControl::handle_fstat;
83	    sim_syscall_table[16] = &SimControl::handle_fstatat;
84	    sim_syscall_table[17] = &SimControl::handle_link;
85	    sim_syscall_table[18] = &SimControl::handle_lstat;
86	    sim_syscall_table[19] = &SimControl::handle_stat;
87	    sim_syscall_table[20] = &SimControl::handle_openat;
88	    sim_syscall_table[21] = &SimControl::handle_rename;
89	    sim_syscall_table[22] = &SimControl::handle_unlink;
90	
91	    this->socket.register_b_transport(this, &SimControl::b_transport);
