103	  SimpleMemory<BusWidth>& data_region;
104	  sc_core::sc_signal<sc_dt::sc_uint<31>>& int_trigger;
105	  const sc_core::sc_clock& clk;
106	  sys_func_ptr sim_syscall_table[SYSCALL_TABLE_SIZE] = {};
107	  uint32_t riscv_xlen;
108	  uint64_t partial_htif_command;
109	  int htif_parts_received;
