111	  void handle_trans(tlm::tlm_generic_payload& trans)
112	  {
113	    const auto addr = trans.get_address();
114	    const auto len = trans.get_data_length();
115	    const auto buf = std::span{trans.get_data_ptr(), len};
116	    const auto offset = addr - region.base_address;
117	
118	    if (trans.is_read()) {
119	      spdlog::debug("sim_control: read, addr={:#x}, len={}", addr, len);
120	      return;
121	    }
122	
123	    spdlog::debug("sim_control: write, addr={:#x}, len={}", addr, len);
124	
125	    if (offset == 0 && len == 4) {
126	      handle_sim_command(unpack<uint32_t>(buf));
127	    } else if (offset == HTIF_PUTCHAR_OFFSET && len == 1) {
128	      std::putchar(buf[0]);
129	    } else if (offset == HTIF_CMD_OFFSET) {
130	      (len == 8) ? handle_htif_64bit_write(buf)
131	                 : handle_htif_32bit_low_write(buf);
132	    } else if (offset == HTIF_CMD_HIGH_OFFSET && len == 4) {
133	      handle_htif_32bit_high_write(buf);
134	    } else if (offset == INT_TRIGGER_OFFSET && len == 4) {
135	      auto val = unpack<uint32_t>(buf);
136	      spdlog::debug("sim_control: int_trigger = {:#x}", val);
137	      int_trigger.write(val);
138	      // clear the IRQ after one cycle
139	      if (val != 0) {
140	        wait(clk.posedge_event());
141	        int_trigger.write(0);
142	      }
143	    } else {
144	      spdlog::warn("sim_control: spurious write at {:#x}, length {}", addr,
145	                   len);
146	    }
147	  }
148	
149	  void handle_sim_command(uint32_t command)
150	  {
151	    spdlog::info("sim_control: received command {:#x}", command);
152	    switch (static_cast<SimCommand>(command)) {
153	    case SimCommand::NEWLINE:
154	      std::putchar('\n');
155	      break;
156	    case SimCommand::TEST_ILM:
157	      subport_test = SubPortTest::TEST_ILM;
158	      custom_master_sem.post();
159	      break;
160	    case SimCommand::TEST_DLM:
161	      subport_test = SubPortTest::TEST_DLM;
162	      custom_master_sem.post();
163	      break;
164	    case SimCommand::TEST_HVM:
165	      subport_test = SubPortTest::TEST_HVM;
166	      custom_master_sem.post();
167	      break;
168	    case SimCommand::PASSED:
169	    case SimCommand::FINISHED:
170	      spdlog::info("sim_control: Test PASSED");
171	      exits = 0;
172	      break;
173	    case SimCommand::SKIPPED:
174	      spdlog::info("sim_control: Test SKIPPED");
175	      exits = 0;
176	      break;
177	    case SimCommand::FAILED:
178	      spdlog::info("sim_control: Test FAILED");
179	      exits = 1;
180	      break;
181	    case SimCommand::WARNING:
182	      spdlog::warn("sim_control: Test WARNING");
183	      exits = 1;
184	      break;
185	    default:
186	      if (command < 256)
187	        exits = command;
188	      else
189	        spdlog::warn("sim_control: unknown command {:#x}", command);
190	      break;
191	    }
192	  }
193	
194	  template<typename T>
195	  static T unpack(const std::span<uint8_t>& buf)
196	  {
197	    T result = 0;
198	    for (size_t i = 0; i < sizeof(T); ++i)
199	      result |= static_cast<T>(buf[i]) << (i * 8);
200	    return result;
201	  }
202	
203	  void execute_htif_syscall()
204	  {
205	    command_t cmd(partial_htif_command);
206	    if (cmd.device() != 0 || cmd.cmd() != 0) {
207	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
208	      return;
209	    }
210	    dispatch(cmd);
211	    partial_htif_command = 0;
212	    htif_parts_received = 0;
213	  }
214	
215	  void handle_htif_64bit_write(const std::span<uint8_t>& buf)
216	  {
217	    command_t cmd(unpack<uint64_t>(buf));
218	    if (cmd.device() == 0 && cmd.cmd() == 0)
219	      dispatch(cmd);
220	    else
221	      spdlog::warn("sim_control: unknown device: #{}", cmd.device());
222	  }
223	
224	  void handle_htif_32bit_low_write(const std::span<uint8_t>& buf)
225	  {
226	    partial_htif_command |= unpack<uint32_t>(buf);
227	    if (++htif_parts_received == HTIF_32BIT_PARTS)
228	      execute_htif_syscall();
229	  }
230	
231	  void handle_htif_32bit_high_write(const std::span<uint8_t>& buf)
232	  {
233	    partial_htif_command |= static_cast<uint64_t>(unpack<uint32_t>(buf)) << 32;
234	    if (++htif_parts_received == HTIF_32BIT_PARTS)
235	      execute_htif_syscall();
236	  }
237	
238	  void dispatch(command_t cmd)
239	  {
240	    uint64_t syscall_args[MAGIC_MEM_SIZE];
241	    auto addr_offset = cmd.payload() - data_region.region.base_address;
242	    auto src = data_region.data.begin() + addr_offset;
243	
244	    std::copy(src, src + sizeof(syscall_args),
245	              reinterpret_cast<uint8_t*>(syscall_args));
246	
247	    spdlog::debug("sim_control: args: {:#x}, {:#x}, {:#x}, "
248	                  "{:#x}, {:#x}, {:#x}, {:#x}",
249	                  syscall_args[0], syscall_args[1], syscall_args[2],
250	                  syscall_args[3], syscall_args[4], syscall_args[5],
251	                  syscall_args[6]);
252	
253	    auto syscall_num = syscall_args[0];
254	    if (syscall_num >= SYSCALL_TABLE_SIZE || !sim_syscall_table[syscall_num]) {
255	      spdlog::critical("sim_control: invalid syscall number {}", syscall_num);
256	      syscall_args[0] = static_cast<uint64_t>(-1);
257	    } else {
258	      syscall_args[0] = (this->*sim_syscall_table[syscall_num])(
259	        syscall_args[1], syscall_args[2], syscall_args[3], syscall_args[4],
260	        syscall_args[5], syscall_args[6], syscall_args[7]);
261	    }
262	
263	    std::copy(reinterpret_cast<uint8_t*>(syscall_args),
264	              reinterpret_cast<uint8_t*>(syscall_args) + sizeof(syscall_args),
265	              src);
266	  }
267	};
